package in.aicon.pocket;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class ResetStoreTest {
 SQLiteDatabase db;LedgerSyncStore sync;ResetStore reset;String subject="456789012345678901234";
 @Before public void setup()throws Exception{Context c=RuntimeEnvironment.getApplication();c.deleteDatabase(AccountScope.databaseFor(subject));db=c.openOrCreateDatabase(AccountScope.databaseFor(subject),0,null);sync=new LedgerSyncStore(db,subject);reset=new ResetStore(db,subject);db.beginTransaction();try{new CatalogStore(db).seed(new String[]{"Food"},new String[]{"Cash"});ContentValues v=new ContentValues();v.put("uuid",UUID.randomUUID().toString());v.put("kind","income");v.put("amount",100);v.put("day","2026-11-11");v.put("account","Cash");v.put("dest","");v.put("category","Food");v.put("note","private note");db.insertOrThrow("tx",null,v);sync.captureLocalEdits();db.setTransactionSuccessful();}finally{db.endTransaction();}}
 @After public void close(){db.close();}
 long count(String table){try(Cursor c=db.rawQuery("SELECT count(*) FROM "+table,null)){c.moveToFirst();return c.getLong(0);}}
 @Test public void explicitAcknowledgmentClearsAllFinancialAndOutboxBytesAtomically()throws Exception{long previous=sync.snapshot().revision;ResetBarrier.Check observed=reset.view().inspect(Collections.singleton(UUID.randomUUID().toString()));db.beginTransaction();try{reset.applyObserved(observed);db.setTransactionSuccessful();}finally{db.endTransaction();}for(String table:new String[]{"tx","budgets","goals","catalog","preferences","cloud_records","cloud_outbox"})assertEquals(0,count(table));assertEquals(1,reset.view().known.size());assertTrue(sync.snapshot().revision>previous);assertEquals(1,count("reset_history"));assertEquals(3,count("cloud_meta"));}
 @Test public void rollbackKeepsFinancialDataPendingUploadsAndPriorBarrierView()throws Exception{long previous=sync.snapshot().revision,pending=count("cloud_outbox");ResetBarrier.Check observed=reset.view().inspect(Collections.singleton(UUID.randomUUID().toString()));db.beginTransaction();try{reset.applyObserved(observed);}finally{db.endTransaction();}assertEquals(1,count("tx"));assertEquals(pending,count("cloud_outbox"));assertEquals(previous,sync.snapshot().revision);assertTrue(reset.view().known.isEmpty());}
 @Test public void untransactionalOrStaleAcknowledgmentCannotClearLedger()throws Exception{ResetBarrier.Check first=reset.view().inspect(Collections.singleton(UUID.randomUUID().toString()));try{reset.applyObserved(first);fail();}catch(IllegalStateException expected){}assertEquals(1,count("tx"));db.beginTransaction();try{reset.applyObserved(first);db.setTransactionSuccessful();}finally{db.endTransaction();}db.beginTransaction();try{try{reset.applyObserved(first);fail();}catch(IllegalStateException expected){}}finally{db.endTransaction();}assertEquals(first.remote.known,reset.view().known);}
}
